import docker
import os
import requests
import subprocess
from IQCommon.common import JUPYTERHUB_IP_PORT
from IQCommon.exception import get_traceback_message
from IQCommon.logger import system_log
from IQCommon.util.trade_info_utils import get_trade_list
def delete_user_docker(user_id):
    """
    删除账户容器
    :param user_id: 账户ID
    :type user_id: str
    :return: 是否清理账户容器：False，否；True，是。
    :rtype: bool
    """
    trade_list = get_trade_list(user_id, strategy_type='trade')
    if len(trade_list) == 0 and len(os.popen('sudo docker ps -a | grep jupyter-{}'.format(user_id)).readlines()) != 0:
        system_log.info('账户{}已不存在运行中的交易，删除对应账户容器'.format(user_id))
        os.system('docker rm -f jupyter-{}'.format(user_id))
        return True
    return False
def get_docker_status(user_id, docker_client=None, log_flag=True):
    """
    获取用户容器状态
    :param user_id: 账户ID
    :type user_id: str
    :param docker_client: docker客户端
    :type docker_client: docker.DockerClient
    :param log_flag: 是否打印日志
    :type log_flag: bool
    return: 容器是否运行：False，否；True，是。
    :rtype: bool
    """
    docker_status = False
    try:
        if docker_client is None:
            docker_client = docker.DockerClient(base_url='unix://var/run/docker.sock', version='auto')
        container_info = docker_client.api.inspect_container('jupyter-{}'.format(user_id))
        notebook_port = container_info['NetworkSettings']['Ports']['8888/tcp'][0]['HostPort']
        response = requests.get('http://127.0.0.1:{}'.format(notebook_port))
        if response.status_code <= 404:
            docker_status = True
    except BaseException:
        if log_flag is True:
            system_log.warning('获取账户{}容器状态失败，错误原因：{}'.format(user_id, get_traceback_message()))
    return docker_status
def start_user_docker(user_id, action_type=None, python_version=None):
    """
    拉起账户容器
    :param user_id: 账户ID
    :type user_id: str
    :param action_type: 操作类型：0，需要前置操作；1，不需要前置操作。
    :type action_type: str
    :param python_version: 拉起用户容器Python版本：py35；py311。
    :type python_version: str
    :return: 拉起容器结果
    :rtype: dict
    """
    system_log.info('账户{}执行拉起容器操作'.format(user_id))
    try:
        kwargs = {'user': user_id}
        if action_type is not None:
            kwargs['action_type'] = action_type
        if python_version is not None:
            kwargs['python_version'] = python_version
        response = requests.post('http://{}/hub/startdocker'.format(JUPYTERHUB_IP_PORT), data=kwargs)
        return response.json()
        return None
    except BaseException:
        error_message = '拉起账户{}容器失败，错误原因：{}'.format(user_id, get_traceback_message())
        system_log.error(error_message)
        return {'error_no': -1, 'error_info': error_message}
def is_service_active(service_name):
    """检查服务是否存在"""
    try:
        subprocess.run(['systemctl', 'is-active', '--quiet', service_name], check=True)
        return True
    except subprocess.CalledProcessError:
        return False
def stop_docker_services():
    """停止docker.socket和docker.service服务"""
    if is_service_active('docker.socket'):
        subprocess.run(['systemctl', 'stop', 'docker.socket'])
    if is_service_active('docker.service'):
        subprocess.run(['systemctl', 'stop', 'docker.service'])
        return None
def get_container_id(user_id):
    """获取容器ID"""
    try:
        docker_client = docker.from_env()
        container = docker_client.containers.get('jupyter-{}'.format(user_id))
        return container.id
        return None
    except BaseException:
        return None
